using Silksong_Rando_Logic_Manager.Data;

namespace Silksong_Rando_Logic_Manager.Services;

// These mappers intentionally list fields rather than deriving them from CLR
// properties. Resolver IDs and lifecycle fields are never ordinary write fields.
public sealed class SubroomFieldDiffMapper : ChildMapper<Subroom>
{
    public override IReadOnlyList<string> EditableFields { get; } = [nameof(Subroom.FriendlyName), nameof(Subroom.ReferenceId), nameof(Subroom.Notes), nameof(Subroom.SceneUnitX), nameof(Subroom.SceneUnitY), nameof(Subroom.SceneUnitWidth), nameof(Subroom.SceneUnitHeight)];
    protected override object? Get(Subroom x, string f) => f switch { nameof(Subroom.FriendlyName) => x.FriendlyName, nameof(Subroom.ReferenceId) => x.ReferenceId, nameof(Subroom.Notes) => x.Notes, nameof(Subroom.SceneUnitX) => x.SceneUnitX, nameof(Subroom.SceneUnitY) => x.SceneUnitY, nameof(Subroom.SceneUnitWidth) => x.SceneUnitWidth, nameof(Subroom.SceneUnitHeight) => x.SceneUnitHeight, _ => throw new ArgumentOutOfRangeException(nameof(f)) };
    protected override void Set(Subroom x, string f, object? v) { switch (f) { case nameof(Subroom.FriendlyName): x.FriendlyName=(string)v!; break; case nameof(Subroom.ReferenceId): x.ReferenceId=(string)v!; break; case nameof(Subroom.Notes): x.Notes=(string)v!; break; case nameof(Subroom.SceneUnitX): x.SceneUnitX=(double?)v; break; case nameof(Subroom.SceneUnitY): x.SceneUnitY=(double?)v; break; case nameof(Subroom.SceneUnitWidth): x.SceneUnitWidth=(double?)v; break; case nameof(Subroom.SceneUnitHeight): x.SceneUnitHeight=(double?)v; break; default: throw new ArgumentOutOfRangeException(nameof(f)); } }
    public override Subroom Clone(Subroom x) => new() { Id=x.Id, RoomId=x.RoomId, FriendlyName=x.FriendlyName, ReferenceId=x.ReferenceId, Notes=x.Notes, SceneUnitX=x.SceneUnitX, SceneUnitY=x.SceneUnitY, SceneUnitWidth=x.SceneUnitWidth, SceneUnitHeight=x.SceneUnitHeight, SortOrder=x.SortOrder, IsArchived=x.IsArchived, ArchivedUtc=x.ArchivedUtc, CreatedUtc=x.CreatedUtc, UpdatedUtc=x.UpdatedUtc };
}

