    protected override object? Get(SubroomConnection x,string f)=>f switch { nameof(SubroomConnection.Alias)=>x.Alias,nameof(SubroomConnection.FriendlyName)=>x.FriendlyName,nameof(SubroomConnection.SourceSubroomReferenceText)=>x.SourceSubroomReferenceText,nameof(SubroomConnection.DestinationSubroomReferenceText)=>x.DestinationSubroomReferenceText,nameof(SubroomConnection.Requirements)=>x.Requirements,nameof(SubroomConnection.Notes)=>x.Notes,nameof(SubroomConnection.EnableAnnotation)=>x.EnableAnnotation,nameof(SubroomConnection.SceneUnitX)=>x.SceneUnitX,nameof(SubroomConnection.SceneUnitY)=>x.SceneUnitY,nameof(SubroomConnection.IsTodo)=>x.IsTodo,nameof(SubroomConnection.IsVerified)=>x.IsVerified,_=>throw new ArgumentOutOfRangeException(nameof(f))};
    protected override void Set(SubroomConnection x,string f,object? v) { switch(f) { case nameof(SubroomConnection.Alias):x.Alias=(string)v!;break;case nameof(SubroomConnection.FriendlyName):x.FriendlyName=(string)v!;break;case nameof(SubroomConnection.SourceSubroomReferenceText):x.SourceSubroomReferenceText=(string)v!;break;case nameof(SubroomConnection.DestinationSubroomReferenceText):x.DestinationSubroomReferenceText=(string)v!;break;case nameof(SubroomConnection.Requirements):x.Requirements=(string)v!;break;case nameof(SubroomConnection.Notes):x.Notes=(string)v!;break;case nameof(SubroomConnection.EnableAnnotation):x.EnableAnnotation=(bool)v!;break;case nameof(SubroomConnection.SceneUnitX):x.SceneUnitX=(double?)v;break;case nameof(SubroomConnection.SceneUnitY):x.SceneUnitY=(double?)v;break;case nameof(SubroomConnection.IsTodo):x.IsTodo=(bool)v!;break;case nameof(SubroomConnection.IsVerified):x.IsVerified=(bool?)v;break;default:throw new ArgumentOutOfRangeException(nameof(f));}}
    public override SubroomConnection Clone(SubroomConnection x)=>new(){Id=x.Id,RoomId=x.RoomId,Alias=x.Alias,FriendlyName=x.FriendlyName,SourceSubroomReferenceText=x.SourceSubroomReferenceText,DestinationSubroomReferenceText=x.DestinationSubroomReferenceText,Requirements=x.Requirements,RequirementsParseSucceeded=x.RequirementsParseSucceeded,Notes=x.Notes,EnableAnnotation=x.EnableAnnotation,SceneUnitX=x.SceneUnitX,SceneUnitY=x.SceneUnitY,ResolvedSourceSubroomId=x.ResolvedSourceSubroomId,ResolvedDestinationSubroomId=x.ResolvedDestinationSubroomId,SortOrder=x.SortOrder,IsTodo=x.IsTodo,IsVerified=x.IsVerified,IsArchived=x.IsArchived,ArchivedUtc=x.ArchivedUtc,CreatedUtc=x.CreatedUtc,UpdatedUtc=x.UpdatedUtc};
    protected override void CopyDerived(SubroomConnection target, SubroomConnection committed) => target.RequirementsParseSucceeded=committed.RequirementsParseSucceeded;
    protected override void CopyResolver(SubroomConnection target, SubroomConnection committed) { target.ResolvedSourceSubroomId=committed.ResolvedSourceSubroomId; target.ResolvedDestinationSubroomId=committed.ResolvedDestinationSubroomId; }
}

