public abstract class ChildMapper<T> : IChildRowFieldDiffMapper<T> where T : ArchivableEntity
{
    public abstract IReadOnlyList<string> EditableFields { get; }
    public abstract T Clone(T value);
    protected abstract object? Get(T value,string field); protected abstract void Set(T value,string field,object? source);
    protected virtual void CopyDerived(T target,T committed) { }
    protected virtual void CopyResolver(T target,T committed) { }
    public IReadOnlyList<string> Differences(T baseline,T draft)=>EditableFields.Where(f=>!Equals(Get(baseline,f),Get(draft,f))).ToArray();
    public void Apply(T target,T source,IEnumerable<string> fields) { foreach(var f in fields) Set(target,f,Get(source,f)); }
    public void Reconcile(T live,T committed,T request,IReadOnlyCollection<string> fields,bool resolved) { foreach(var f in fields) if(Equals(Get(live,f),Get(request,f))) Set(live,f,Get(committed,f)); live.UpdatedUtc=committed.UpdatedUtc; CopyDerived(live,committed); if(resolved) CopyResolver(live,committed); }
}
